package com.valor.auth;
import org.springframework.context.annotation.*; import org.springframework.stereotype.Component; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.*; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import com.valor.response.ApiResponse; import java.util.*;
@Component class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final UserRepo users; final PermissionService permissions; JwtFilter(JwtService j,UserRepo u,PermissionService p){jwt=j;users=u;permissions=p;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,java.io.IOException {String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{User u=users.findById(jwt.subject(h.substring(7))).orElse(null);if(u!=null&&u.isActive()&&!u.isLocked()&&(u.getLockedUntil()==null||!u.getLockedUntil().isAfter(java.time.LocalDateTime.now()))){List<org.springframework.security.core.GrantedAuthority> auth=new ArrayList<>();auth.add(()->"ROLE_"+u.getRole());permissions.permissionsFor(u.getRole()).forEach(pv->auth.add(()->"PERM_"+pv));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.getId(),null,auth));}}catch(Exception ignored){} c.doFilter(r,s);}}
